@sig trait OutcomeQualification_Api {
  def id: Art.BridgeId
  def outcome_boundary_facts_Id : Art.PortId
  def prior_order_state_Id : Art.PortId
  def qualified_outcome_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualified_outcome: Factory_Dispatch_Coordinator.QualifiedOutcome.Type = $

  def put_qualified_outcome(value : Factory_Dispatch_Coordinator.QualifiedOutcome.Type) : Unit = {
    Contract(
      Modifies(qualified_outcome),
      Ensures(
        qualified_outcome == value
      )
    )
    Spec {
      qualified_outcome = value
    }

    Art.putValue(qualified_outcome_Id, Factory_Dispatch_Coordinator.QualifiedOutcome_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

